    # ── triggers ──
    op.execute("CREATE TRIGGER update_document_timestamp \n                AFTER UPDATE ON document_repository\n                BEGIN\n                    UPDATE document_repository SET updated_at = CURRENT_TIMESTAMP WHERE id = NEW.id;\n                END")
    op.execute("CREATE TRIGGER notify_parent_on_grade\n        AFTER INSERT ON student_grades\n        BEGIN\n            INSERT INTO parent_notifications (\n                parent_id,\n                student_id,\n                notification_type,\n                notification_content,\n                created_date,\n                read_status\n            )\n            SELECT\n                psr.parent_id,\n                NEW.student_id,\n                'grade',\n                'New grade recorded: ' || NEW.assessment_name || ' - ' || NEW.grade,\n                datetime('now'),\n                0\n            FROM parent_student_relationships psr\n            JOIN parent_preferences pp ON psr.parent_id = pp.parent_id\n            WHERE psr.student_id = NEW.student_id AND pp.grade_alerts = 1;\n        END")
    op.execute("CREATE TRIGGER notify_parent_on_absence\n        AFTER INSERT ON attendance\n        WHEN NEW.status != 'present'\n        BEGIN\n            INSERT INTO parent_notifications (\n                parent_id,\n                student_id,\n                notification_type,\n                notification_content,\n                created_date,\n                read_status\n            )\n            SELECT\n                psr.parent_id,\n                NEW.student_id,\n                'attendance',\n                'Absence recorded: ' || NEW.status || ' on ' || NEW.date,\n                datetime('now'),\n                0\n            FROM parent_student_relationships psr\n            JOIN parent_preferences pp ON psr.parent_id = pp.parent_id\n            WHERE psr.student_id = NEW.student_id AND pp.attendance_alerts = 1;\n        END")
    op.execute("CREATE TRIGGER rooms_building_sync_ins\n                        AFTER INSERT ON rooms\n                        WHEN NEW.building_id IS NOT NULL AND NEW.building IS NULL\n                        BEGIN\n                            UPDATE rooms SET building = (\n                                SELECT building_name FROM buildings\n                                WHERE building_id = NEW.building_id\n                            ) WHERE rowid = NEW.rowid;\n                        END")
    op.execute("CREATE TRIGGER rooms_building_sync_upd\n                        AFTER UPDATE OF building_id ON rooms\n                        WHEN NEW.building_id IS NOT NULL\n                        BEGIN\n                            UPDATE rooms SET building = (\n                                SELECT building_name FROM buildings\n                                WHERE building_id = NEW.building_id\n                            ) WHERE rowid = NEW.rowid;\n                        END")


